/// Shared focus traversal for the tab, radio and toggle collections.
#[doc(hidden)]
pub struct RovingFocus {
    pub handles: Vec<Option<gpui_kit::FocusHandle>>,
    active: gpui_kit::Entity<Option<gpui_kit::FocusHandle>>,
}
impl RovingFocus {
    pub fn new(
        id: gpui_kit::ElementId,
        items: &[(gpui_kit::ElementId, bool)],
        selected: Option<usize>,
        window: &mut gpui_kit::Window,
        cx: &mut App,
    ) -> Self {
        let active =
            window.use_keyed_state((id, "active"), cx, |_, _| None::<gpui_kit::FocusHandle>);
        let mut handles: Vec<_> = items
            .iter()
            .map(|(id, disabled)| {
                let handle = window
                    .use_keyed_state((id.clone(), "focus"), cx, |_, cx| cx.focus_handle())
                    .read(cx)
                    .clone();
                handle.clone().tab_stop(false);
                (!disabled).then_some(handle)
            })
            .collect();
        let index = handles
            .iter()
            .position(|h| h.as_ref().is_some_and(|h| h.is_focused(window)))
            .or(selected.filter(|&i| handles.get(i).is_some_and(Option::is_some)))
            .or_else(|| {
                handles
                    .iter()
                    .position(|h| h.is_some() && h.as_ref() == active.read(cx).as_ref())
            })
            .or_else(|| handles.iter().position(Option::is_some));
        if let Some(index) = index {
            let handle = handles[index].as_ref().unwrap().clone().tab_stop(true);
            handles[index] = Some(handle.clone());
            active.update(cx, |value, _| *value = Some(handle));
        }
        Self { handles, active }
    }
    pub fn key(
        &self,
        event: &gpui_kit::KeyDownEvent,
        axis: Option<gpui_kit::Axis>,
        window: &mut gpui_kit::Window,
        cx: &mut App,
    ) -> Option<usize> {
        if event.keystroke.modifiers.modified() {
            return None;
        }
        let enabled: Vec<_> = self
            .handles
            .iter()
            .enumerate()
            .filter_map(|(i, h)| h.as_ref().map(|h| (i, h)))
            .collect();
        let current = enabled.iter().position(|(_, h)| h.is_focused(window))?;
        let direction = UiTheme::read(cx).direction;
        let next = match direction.logical_key(event.keystroke.key.as_str()) {
            "home" => 0,
            "end" => enabled.len() - 1,
            "left" if axis != Some(gpui_kit::Axis::Vertical) => {
                (current + enabled.len() - 1) % enabled.len()
            }
            "right" if axis != Some(gpui_kit::Axis::Vertical) => (current + 1) % enabled.len(),
            "up" if axis != Some(gpui_kit::Axis::Horizontal) => {
                (current + enabled.len() - 1) % enabled.len()
            }
            "down" if axis != Some(gpui_kit::Axis::Horizontal) => (current + 1) % enabled.len(),
            _ => return None,
        };
        enabled[current].1.clone().tab_stop(false);
        let handle = enabled[next].1.clone().tab_stop(true);
        handle.focus(window, cx);
        self.active.update(cx, |value, _| *value = Some(handle));
        window.refresh();
        cx.stop_propagation();
        Some(enabled[next].0)
    }
}

//! Nova-styled Avatar with native image loading and error fallback.

use gpui_kit::{
    App, ElementId, ImageSource, InteractiveElement as _, IntoElement, ObjectFit, ParentElement,
    Pixels, RenderOnce, Rgba, SharedString, StatefulInteractiveElement as _, Styled, StyledImage,
    Window, div, px,
};

use gpui_kit::base::TestSupportExt as _;

use super::theme::{
    UiText, UiTheme,
    locale::{self, DirectionalStyled as _},
    primitives::clipped_image_with,
};

/// A compact, circular Avatar with an optional image and fallback content.
#[derive(IntoElement)]
pub struct Avatar {
    style: gpui_kit::StyleRefinement,
    id: ElementId,
    image: Option<ImageSource>,
    fallback: SharedString,
    aria_label: Option<SharedString>,
    size: AvatarSize,
    status: Option<AvatarStatus>,
    status_size: Option<Pixels>,
    ring_color: Option<Rgba>,
}

/// A presence state drawn as a dot over the avatar's bottom-right corner.
///
/// The colors come from the theme: `success` for online, `warning` for away,
/// `destructive` for do not disturb, and a hollow `muted_foreground` ring for
/// offline. Set those tokens to change every presence dot at once.
#[derive(Clone, Debug, PartialEq)]
pub enum AvatarStatus {
    /// Active now: a filled `success` dot.
    Online,
    /// Idle or away: a filled `warning` dot.
    Away,
    /// Do not disturb: a filled `destructive` dot.
    Dnd,
    /// Not connected: a hollow ring, so it reads without color.
    Offline,
    /// An app-defined state with its own color and the words read after the name.
    Custom {
        /// The dot fill.
        color: Rgba,
        /// The status read after the accessible name, such as "in a meeting".
        label: SharedString,
    },
}

impl AvatarStatus {
    /// The words appended to the avatar's accessible name, translated with
    /// the application's strings.
    pub fn text(&self, cx: &App) -> SharedString {
        let text = match self {
            Self::Online => UiText::StatusOnline,
            Self::Away => UiText::StatusAway,
            Self::Dnd => UiText::StatusDnd,
            Self::Offline => UiText::StatusOffline,
            Self::Custom { label, .. } => return label.clone(),
        };
        locale::text(cx, text)
    }

    /// The English words appended to the avatar's accessible name.
    pub fn label(&self) -> SharedString {
        match self {
            Self::Online => "online".into(),
            Self::Away => "away".into(),
            Self::Dnd => "do not disturb".into(),
            Self::Offline => "offline".into(),
            Self::Custom { label, .. } => label.clone(),
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
/// Nova avatar dimensions.
pub enum AvatarSize {
    /// Compact dimensions.
    Sm,
    #[default]
    /// The default Nova presentation.
    Default,
    /// Large dimensions.
    Lg,
}

impl Avatar {
    /// Creates a `Avatar` with a stable caller-owned ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui_kit::StyleRefinement::default(),
            id: id.into(),
            image: None,
            fallback: SharedString::default(),
            aria_label: None,
            size: AvatarSize::Default,
            status: None,
            status_size: None,
            ring_color: None,
        }
    }

    /// Sets the text shown while the image is unavailable.
    pub fn fallback(mut self, text: impl Into<SharedString>) -> Self {
        self.fallback = text.into();
        self
    }
    /// Sets the avatar image source.
    pub fn image(mut self, source: impl Into<ImageSource>) -> Self {
        self.image = Some(source.into());
        self
    }
    /// Sets the accessible name of the control.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }
    /// Selects the Nova control dimensions.
    pub fn size(mut self, size: AvatarSize) -> Self {
        self.size = size;
        self
    }
    /// Draws a presence dot at the bottom-right corner, sized to the avatar,
    /// and appends the status to the accessible name ("Ana Lopez, away").
    pub fn status(mut self, status: AvatarStatus) -> Self {
        self.status = Some(status);
        self
    }
    /// Sets the presence dot's diameter, ring included, instead of deriving
    /// it from the avatar's size.
    pub fn status_size(mut self, size: impl Into<Pixels>) -> Self {
        self.status_size = Some(size.into());
        self
    }
    /// Sets the ring drawn behind the presence dot. It should match the
    /// surface under the avatar; the default is the `background` token, so
    /// pass `colors.sidebar` for avatars in a sidebar.
    pub fn ring_color(mut self, color: impl Into<Rgba>) -> Self {
        self.ring_color = Some(color.into());
        self
    }
}

/// The presence dot's outer diameter (ring included) and ring width for an
/// avatar of `size` pixels.
///
/// The three `AvatarSize` presets get 11, 14 and 16px dots. An avatar drawn
/// at another width, through `.w()` or `.size()`, gets a third of its width,
/// clamped to 6 to 14px, so an 18px avatar does not lose its face to the dot.
fn status_metrics(size: f32, preset: bool, theme: &UiTheme) -> (Pixels, Pixels) {
    let ring_width = px(if size < 24. {
        1.
    } else if size < 32. {
        1.5
    } else {
        2.
    });
    if preset {
        // 8, 10 and 12px dots for the 24, 32 and 40px avatars.
        return (theme.space(size / 16. + 0.5) + ring_width * 2., ring_width);
    }
    (px((size / 3.).clamp(6., 14.)), ring_width)
}

/// The presence dot and its surface ring, `outer` across with the ring.
fn status_dot(
    status: &AvatarStatus,
    outer: Pixels,
    ring_width: Pixels,
    ring: Rgba,
    theme: &UiTheme,
) -> gpui_kit::Div {
    let ring_width = ring_width.min(outer / 4.);
    let dot = div().size_full().rounded_full();
    let dot = match status {
        AvatarStatus::Online => dot.bg(theme.colors.success),
        AvatarStatus::Away => dot.bg(theme.colors.warning),
        AvatarStatus::Dnd => dot.bg(theme.colors.destructive),
        AvatarStatus::Custom { color, .. } => dot.bg(*color),
        AvatarStatus::Offline => dot
            .bg(ring)
            .border(ring_width)
            .border_color(theme.colors.muted_foreground),
    };
    div()
        .debug_selector(|| "avatar-status".into())
        .absolute()
        .inset_end(theme.direction, px(-1.))
        .bottom(px(-1.))
        .size(outer)
        .p(ring_width)
        .rounded_full()
        .bg(ring)
        .child(dot)
}

impl RenderOnce for Avatar {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let size = match self.size {
            AvatarSize::Sm => 24.,
            AvatarSize::Default => 32.,
            AvatarSize::Lg => 40.,
        };
        let image_size = theme.space(size / 4.);
        // A width set through `Styled` wins over the preset for the dot.
        let styled_width = match self.style.size.width {
            Some(gpui_kit::Length::Definite(gpui_kit::DefiniteLength::Absolute(
                gpui_kit::AbsoluteLength::Pixels(width),
            ))) if width != image_size => Some(width),
            _ => None,
        };
        let dot = self.status.as_ref().map(|status| {
            let (outer, ring_width) = match (self.status_size, styled_width) {
                (Some(outer), width) => (
                    outer,
                    status_metrics(width.map_or(size, f32::from), false, &theme).1,
                ),
                (None, Some(width)) => status_metrics(f32::from(width), false, &theme),
                (None, None) => status_metrics(size, true, &theme),
            };
            status_dot(
                status,
                outer,
                ring_width,
                self.ring_color.unwrap_or(theme.colors.background),
                &theme,
            )
        });
        let label = match (self.aria_label, &self.status) {
            (Some(label), Some(status)) => Some(format!("{}, {}", label, status.text(cx)).into()),
            (label, _) => label,
        };
        let frame_theme = theme.clone();
        let fallback = move || {
            div()
                .size_full()
                .flex()
                .items_center()
                .justify_center()
                .rounded_full()
                .bg(theme.colors.muted)
                .text_color(theme.colors.muted_foreground)
                .text_size(theme.text(if self.size == AvatarSize::Sm {
                    12.
                } else {
                    14.
                }))
                .child(self.fallback.clone())
                .into_any_element()
        };
        let root = match self.image {
            Some(source) => {
                let loading = fallback.clone();
                clipped_image_with(
                    source,
                    image_size / 2.,
                    ObjectFit::Cover,
                    &frame_theme,
                    |image| image.with_loading(loading).with_fallback(fallback),
                )
            }
            None => div().rounded_full().overflow_hidden().child(fallback()),
        }
        .size_full();
        // The dot sits outside the circular clip, so the frame is a plain box.
        let root = div()
            .id(self.id)
            .test_support()
            .relative()
            .size(image_size)
            .flex_shrink_0()
            .child(root)
            .children(dot);
        let root = if let Some(label) = label {
            root.aria_label(label)
        } else {
            root
        };
        super::theme::apply_style(root, &self.style)
    }
}

impl gpui_kit::Styled for Avatar {
    fn style(&mut self) -> &mut gpui_kit::StyleRefinement {
        &mut self.style
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui_kit::{
        Context, Render, TestAppContext, VisualTestContext, prelude::FluentBuilder as _,
        test::TestQueryExt as _,
    };

    struct People {
        status: Option<AvatarStatus>,
        size: AvatarSize,
    }

    impl Render for People {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            div().p(px(8.)).child(
                Avatar::new("ana")
                    .aria_label("Ana Lopez")
                    .fallback("AL")
                    .size(self.size)
                    .when_some(self.status.clone(), |avatar, status| avatar.status(status)),
            )
        }
    }

    fn draw(
        status: Option<AvatarStatus>,
        size: AvatarSize,
        cx: &mut TestAppContext,
    ) -> VisualTestContext {
        cx.update(super::super::theme::init);
        let window = cx.add_window(move |_, _| People { status, size });
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx
    }

    #[gpui_kit::test]
    fn the_status_joins_the_accessible_name(cx: &mut TestAppContext) {
        let mut cx = draw(Some(AvatarStatus::Away), AvatarSize::Default, cx);
        cx.update(|window, _| {
            window.find_by_label("Ana Lopez, away");
        });
        assert!(cx.debug_bounds("avatar-status").is_some());
    }

    #[gpui_kit::test]
    fn no_status_draws_no_dot(cx: &mut TestAppContext) {
        let mut cx = draw(None, AvatarSize::Default, cx);
        cx.update(|window, _| {
            window.find_by_label("Ana Lopez");
        });
        assert!(cx.debug_bounds("avatar-status").is_none());
    }

    #[gpui_kit::test]
    fn the_dot_scales_with_the_avatar_and_sits_on_its_corner(cx: &mut TestAppContext) {
        for (size, avatar, dot) in [
            (AvatarSize::Sm, 24., 8. + 3.),
            (AvatarSize::Default, 32., 10. + 4.),
            (AvatarSize::Lg, 40., 12. + 4.),
        ] {
            let mut cx = draw(Some(AvatarStatus::Offline), size, cx);
            let bounds = cx.debug_bounds("avatar-status").expect("the dot is drawn");
            assert_eq!(bounds.size.width, px(dot), "{size:?}");
            // Bottom-right corner of the avatar at (8, 8), overhanging by 1px.
            assert_eq!(bounds.right(), px(8. + avatar + 1.), "{size:?}");
            assert_eq!(bounds.bottom(), px(8. + avatar + 1.), "{size:?}");
        }
    }

    struct Small {
        status_size: Option<Pixels>,
    }

    impl Render for Small {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            div().p(px(8.)).child(
                Avatar::new("dm")
                    .aria_label("Ana Lopez")
                    .fallback("AL")
                    .size(AvatarSize::Sm)
                    .w(px(18.))
                    .h(px(18.))
                    .status(AvatarStatus::Online)
                    .when_some(self.status_size, |avatar, size| avatar.status_size(size)),
            )
        }
    }

    #[gpui_kit::test]
    fn a_resized_avatar_gets_a_dot_a_third_of_its_width(cx: &mut TestAppContext) {
        for (status_size, expected) in [(None, 6.), (Some(px(9.)), 9.)] {
            cx.update(super::super::theme::init);
            let window = cx.add_window(move |_, _| Small { status_size });
            let mut cx = VisualTestContext::from_window(window.into(), cx);
            cx.update(|window, cx| window.draw(cx).clear(cx));
            let bounds = cx.debug_bounds("avatar-status").expect("the dot is drawn");
            assert_eq!(bounds.size.width, px(expected));
            assert_eq!(bounds.right(), px(8. + 18. + 1.));
        }
    }

    #[test]
    fn statuses_read_as_words() {
        assert_eq!(AvatarStatus::Dnd.label(), "do not disturb");
        let custom = AvatarStatus::Custom {
            color: gpui_kit::Rgba::default(),
            label: "in a meeting".into(),
        };
        assert_eq!(custom.label(), "in a meeting");
    }
}

//! The shadcn Nova Button visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `button.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction comes from the
//! GPUI Kit headless button.

use std::rc::Rc;

use gpui_kit::base::Button as BaseButton;
use gpui_kit::{
    AnyElement, App, ClickEvent, ElementId, FontWeight, IntoElement, ParentElement, RenderOnce,
    Rgba, SharedString, Styled, Window, px,
};

use super::theme::{
    UiRadius, UiTheme,
    locale::DirectionalStyled as _,
    primitives::{disabled as disabled_style, focus},
};

type ButtonClickHandler = Rc<dyn Fn(&ClickEvent, &mut Window, &mut App) + 'static>;
type ButtonStyleHandler = Rc<dyn Fn(BaseButton) -> BaseButton>;

/// The pinned shadcn Button visual variant.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonVariant {
    /// Primary action.
    #[default]
    Default,
    /// Bordered action.
    Outline,
    /// Secondary action.
    Secondary,
    /// Low-emphasis action.
    Ghost,
    /// Destructive action.
    Destructive,
    /// Link-styled action.
    Link,
}

/// The pinned shadcn Button size.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonSize {
    /// 24px-high extra-small button.
    Xs,
    /// 28px-high small button.
    Sm,
    /// 32px-high default button.
    #[default]
    Default,
    /// 36px-high large button.
    Lg,
    /// 24px square icon button.
    IconXs,
    /// 28px square icon button.
    IconSm,
    /// 32px square icon button.
    Icon,
    /// 36px square icon button.
    IconLg,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ButtonMetrics {
    height: f32,
    horizontal_padding: f32,
    gap: f32,
    radius: f32,
    text_size: f32,
    icon_only: bool,
}

impl ButtonSize {
    fn metrics(self, radii: UiRadius) -> ButtonMetrics {
        let radius = f32::from(radii.lg);
        let radius_md = f32::from(radii.md);
        match self {
            Self::Xs => ButtonMetrics::new(24.0, 8.0, 4.0, radius_md.min(10.0), 12.0, false),
            Self::Sm => ButtonMetrics::new(28.0, 10.0, 4.0, radius_md.min(12.0), 12.8, false),
            Self::Default => ButtonMetrics::new(32.0, 10.0, 6.0, radius, 14.0, false),
            Self::Lg => ButtonMetrics::new(36.0, 10.0, 6.0, radius, 14.0, false),
            Self::IconXs => ButtonMetrics::new(24.0, 0.0, 0.0, radius_md.min(10.0), 14.0, true),
            Self::IconSm => ButtonMetrics::new(28.0, 0.0, 0.0, radius_md.min(12.0), 14.0, true),
            Self::Icon => ButtonMetrics::new(32.0, 0.0, 0.0, radius, 14.0, true),
            Self::IconLg => ButtonMetrics::new(36.0, 0.0, 0.0, radius, 14.0, true),
        }
    }
}

impl ButtonMetrics {
    const fn new(
        height: f32,
        horizontal_padding: f32,
        gap: f32,
        radius: f32,
        text_size: f32,
        icon_only: bool,
    ) -> Self {
        Self {
            height,
            horizontal_padding,
            gap,
            radius,
            text_size,
            icon_only,
        }
    }
}

/// A styled Button that keeps GPUI Kit's pointer and keyboard behavior.
#[derive(IntoElement)]
pub struct Button {
    style: gpui_kit::StyleRefinement,
    id: ElementId,
    variant: ButtonVariant,
    size: ButtonSize,
    disabled: bool,
    aria_label: Option<SharedString>,
    on_click: Option<ButtonClickHandler>,
    style_with: Option<ButtonStyleHandler>,
    tint: Option<Rgba>,
    children: Vec<AnyElement>,
}

impl Button {
    /// Creates a Button with a caller-owned stable ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui_kit::StyleRefinement::default(),
            id: id.into(),
            variant: ButtonVariant::default(),
            size: ButtonSize::default(),
            disabled: false,
            aria_label: None,
            on_click: None,
            style_with: None,
            tint: None,
            children: Vec::new(),
        }
    }

    /// Sets the visual variant.
    pub fn variant(mut self, variant: ButtonVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Sets the visual size.
    pub fn size(mut self, size: ButtonSize) -> Self {
        self.size = size;
        self
    }

    /// Prevents activation and removes the Button from tab order.
    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    /// Sets the accessible name for icon or custom content. Use `label` for plain text.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Adds visible text and uses it as the accessible name unless one was supplied.
    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        let label = label.into();
        self.aria_label.get_or_insert_with(|| label.clone());
        self.children.push(label.into_any_element());
        self
    }

    /// Runs for pointer, Enter, or Space activation.
    pub fn on_click(
        mut self,
        handler: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_click = Some(Rc::new(handler));
        self
    }

    /// Fills the button with one app-chosen color, such as an integration's
    /// `#3f51b5`. Hover moves the fill toward the text, and the text is the
    /// theme's foreground or background, whichever reads better on the fill,
    /// so it keeps its contrast in light and dark mode. Replaces the variant.
    pub fn tint(mut self, color: impl Into<Rgba>) -> Self {
        self.tint = Some(color.into());
        self
    }

    /// Replaces the visual styling while retaining button interaction.
    /// Include a visible keyboard focus treatment in custom styles.
    pub fn style_with(mut self, handler: impl Fn(BaseButton) -> BaseButton + 'static) -> Self {
        self.style_with = Some(Rc::new(handler));
        self
    }
}

impl ParentElement for Button {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.children.extend(elements);
    }
}

impl RenderOnce for Button {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let variant = self.variant;
        let size = self.size;
        let root = BaseButton::new(self.id).disabled(self.disabled);
        let root = match (self.style_with, self.tint) {
            (Some(style), _) => style(root),
            (None, Some(tint)) => style_tinted_button(root, self.disabled, tint, size, &theme),
            (None, None) => style_button(root, self.disabled, variant, size, &theme),
        };
        let mut root = super::theme::apply_style(root, &self.style).children(self.children);

        if let Some(label) = self.aria_label {
            root = root.accessibility_label(label);
        }
        if let Some(handler) = self.on_click {
            root = root.on_click(move |event, window, cx| handler(event, window, cx));
        }

        root
    }
}

#[doc(hidden)]
pub fn style_button<T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder>(
    base: T,
    disabled: bool,
    variant: ButtonVariant,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    style_button_with(base, disabled, variant, None, size, theme)
}

fn style_button_with<
    T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder,
>(
    base: T,
    disabled: bool,
    variant: ButtonVariant,
    tint: Option<Rgba>,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    let colors = theme.colors;
    let control = theme.control();
    let metrics = size.metrics(theme.radius);
    let invalid_ring = variant == ButtonVariant::Destructive;
    let focus_theme = theme.clone();

    let base = base
        .flex_row_in(theme.direction)
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .whitespace_nowrap()
        .h(theme.space(metrics.height / 4.))
        .gap(theme.space(metrics.gap / 4.))
        .rounded(px(metrics.radius))
        .border_1()
        .border_color(colors.background.opacity(0.0))
        .font_family(theme.fonts.body.clone())
        .font_weight(FontWeight::MEDIUM)
        .text_size(theme.text(metrics.text_size))
        .focus_visible(move |style| focus::ring_for(style, &focus_theme, invalid_ring))
        .when(metrics.icon_only, |base| {
            base.w(theme.space(metrics.height / 4.)).p_0()
        })
        .when(!metrics.icon_only, |base| {
            base.px(theme.space(metrics.horizontal_padding / 4.))
        });

    if let Some(tint) = tint {
        let (fill, hover, foreground) = tint_colors(tint, theme);
        let base = base
            .bg(fill)
            .text_color(foreground)
            .when(!disabled, |base| base.hover(move |style| style.bg(hover)));
        return disabled_style::interactive(base, disabled);
    }
    let base = match variant {
        ButtonVariant::Default => base
            .bg(colors.primary)
            .text_color(colors.primary_foreground)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(colors.primary.opacity(0.80)))
            }),
        ButtonVariant::Outline => base
            .bg(control.background)
            .text_color(colors.foreground)
            .border_color(control.border)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(control.hover).text_color(colors.foreground))
            }),
        ButtonVariant::Secondary => {
            let hover = colors
                .secondary
                .blend(colors.secondary_foreground.opacity(0.08));
            base.bg(colors.secondary)
                .text_color(colors.secondary_foreground)
                .when(!disabled, |base| base.hover(move |style| style.bg(hover)))
        }
        ButtonVariant::Ghost => base
            .bg(colors.background.opacity(0.0))
            .text_color(colors.foreground)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(control.ghost_hover).text_color(colors.foreground))
            }),
        ButtonVariant::Destructive => base
            .bg(control.destructive_background)
            .text_color(colors.destructive)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(control.destructive_hover))
            }),
        ButtonVariant::Link => base
            .bg(colors.background.opacity(0.0))
            .text_color(colors.primary)
            .when(!disabled, |base| base.hover(|style| style.underline())),
    };

    disabled_style::interactive(base, disabled)
}

/// WCAG relative luminance of an opaque color.
fn luminance(color: Rgba) -> f32 {
    let channel = |c: f32| {
        if c <= 0.039_28 {
            c / 12.92
        } else {
            ((c + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * channel(color.r) + 0.7152 * channel(color.g) + 0.0722 * channel(color.b)
}

/// The WCAG contrast ratio between two opaque colors, from 1 to 21.
pub fn contrast_ratio(a: Rgba, b: Rgba) -> f32 {
    let (a, b) = (luminance(a), luminance(b));
    (a.max(b) + 0.05) / (a.min(b) + 0.05)
}

/// The fill, hover fill and text of a button tinted with `tint`.
pub fn tint_colors(tint: Rgba, theme: &UiTheme) -> (Rgba, Rgba, Rgba) {
    let fill = theme.opaque(tint);
    let colors = theme.colors;
    let foreground =
        if contrast_ratio(fill, colors.foreground) >= contrast_ratio(fill, colors.background) {
            colors.foreground
        } else {
            colors.background
        };
    let hover = fill.blend(foreground.opacity(0.14));
    (fill, hover, foreground)
}

#[doc(hidden)]
pub fn style_tinted_button<
    T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder,
>(
    base: T,
    disabled: bool,
    tint: Rgba,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    style_button_with(
        base,
        disabled,
        ButtonVariant::Default,
        Some(tint),
        size,
        theme,
    )
}

impl gpui_kit::Styled for Button {
    fn style(&mut self) -> &mut gpui_kit::StyleRefinement {
        &mut self.style
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tints_pick_readable_text_in_both_themes() {
        let indigo = Rgba::try_from("#3f51b5").unwrap();
        let lime = Rgba::try_from("#cddc39").unwrap();
        for theme in [UiTheme::neutral_light(), UiTheme::neutral_dark()] {
            for tint in [indigo, lime] {
                let (fill, hover, text) = tint_colors(tint, &theme);
                assert!(contrast_ratio(fill, text) >= 4.5, "{tint:?} reads");
                assert_ne!(fill, hover);
            }
            let (_, _, text) = tint_colors(indigo, &theme);
            assert!(luminance(text) > 0.5, "indigo takes light text");
            let (_, _, text) = tint_colors(lime, &theme);
            assert!(luminance(text) < 0.1, "lime takes dark text");
        }
    }

    #[test]
    fn all_variants_expose_clickable_and_disabled_cursors() {
        for theme in [UiTheme::neutral_light(), UiTheme::neutral_dark()] {
            for variant in [
                ButtonVariant::Default,
                ButtonVariant::Outline,
                ButtonVariant::Secondary,
                ButtonVariant::Ghost,
                ButtonVariant::Destructive,
                ButtonVariant::Link,
            ] {
                for disabled in [false, true] {
                    let mut button = style_button(
                        gpui_kit::div(),
                        disabled,
                        variant,
                        ButtonSize::Default,
                        &theme,
                    );
                    assert_eq!(
                        button.style().mouse_cursor,
                        Some(if disabled {
                            gpui_kit::CursorStyle::OperationNotAllowed
                        } else {
                            gpui_kit::CursorStyle::PointingHand
                        })
                    );
                }
            }
        }
    }

    #[test]
    fn nova_sizes_are_exact() {
        let sizes = [
            (ButtonSize::Xs, 24.0, 8.0, 4.0, 8.0),
            (ButtonSize::Sm, 28.0, 10.0, 4.0, 8.0),
            (ButtonSize::Default, 32.0, 10.0, 6.0, 10.0),
            (ButtonSize::Lg, 36.0, 10.0, 6.0, 10.0),
            (ButtonSize::IconXs, 24.0, 0.0, 0.0, 8.0),
            (ButtonSize::IconSm, 28.0, 0.0, 0.0, 8.0),
            (ButtonSize::Icon, 32.0, 0.0, 0.0, 10.0),
            (ButtonSize::IconLg, 36.0, 0.0, 0.0, 10.0),
        ];

        for (size, height, padding, gap, radius) in sizes {
            let metrics = size.metrics(UiRadius::new(px(10.0)));
            assert_eq!(metrics.height, height);
            assert_eq!(metrics.horizontal_padding, padding);
            assert_eq!(metrics.gap, gap);
            assert_eq!(metrics.radius, radius);
        }
    }
}

//! Nova tooltips for pointer hover and keyboard focus.
use super::theme::{UiTheme, primitives::surface};
use gpui_kit::base::{Button, ElementExt as _, Tooltip, TooltipOverlay, TooltipRequest};
use gpui_kit::{
    AnyWindowHandle, App, AppContext as _, Bounds, Context, ElementId, Entity, FocusHandle, Global,
    InteractiveElement as _, ParentElement as _, Pixels, SharedString,
    StatefulInteractiveElement as _, Subscription, WeakEntity, Window, div,
};

/// Adds a tooltip to one existing button, preserving a single focus target.
/// The button must retain its own accessible name.
pub fn tooltip(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    trigger: Button,
    window: &mut Window,
    cx: &mut App,
) -> gpui_kit::Div {
    let state = window.use_keyed_state(id.into(), cx, TooltipState::new);
    state.update(cx, |state, _| state.label = label.into());
    let focus = state.read(cx).focus.clone();
    let overlay = state.read(cx).overlay.clone();
    let hover = state.clone();
    let measured = state.clone();
    div()
        .child(
            trigger
                .track_focus(&focus)
                .on_prepaint(move |bounds, _, cx| {
                    measured.update(cx, |state, _| state.bounds = bounds)
                })
                .on_hover(move |hovered, window, cx| {
                    hover.update(cx, |state, cx| {
                        state.hovered = *hovered;
                        state.update_visibility(window, cx);
                    })
                }),
        )
        .child(overlay)
}

struct TooltipState {
    focus: FocusHandle,
    overlay: Entity<TooltipOverlay>,
    bounds: Bounds<Pixels>,
    label: SharedString,
    hovered: bool,
    active: bool,
    dismissed: bool,
    _subscriptions: [Subscription; 2],
}

/// One Escape interceptor for every tooltip in the application, instead of
/// one keystroke hook per tooltip. Active tooltips register here while shown.
#[derive(Default)]
struct EscapeDismissal {
    shown: Vec<(AnyWindowHandle, WeakEntity<TooltipState>)>,
    _subscription: Option<Subscription>,
}
impl Global for EscapeDismissal {}
impl EscapeDismissal {
    fn install(cx: &mut App) {
        if cx.default_global::<Self>()._subscription.is_some() {
            return;
        }
        let subscription = cx.intercept_keystrokes(|event, window, cx| {
            if event.keystroke.key != "escape" {
                return;
            }
            let handle = window.window_handle();
            let shown = std::mem::take(&mut cx.global_mut::<Self>().shown);
            let mut dismissed = false;
            for (owner, state) in shown {
                if owner != handle {
                    cx.global_mut::<Self>().shown.push((owner, state));
                    continue;
                }
                state
                    .update(cx, |state, cx| {
                        if state.active {
                            state.overlay.update(cx, |overlay, cx| overlay.hide(cx));
                            state.active = false;
                            state.dismissed = true;
                            dismissed = true;
                        }
                    })
                    .ok();
            }
            if dismissed {
                cx.stop_propagation();
            }
        });
        cx.global_mut::<Self>()._subscription = Some(subscription);
    }
    fn shown(window: &Window, state: WeakEntity<TooltipState>, cx: &mut App) {
        let handle = window.window_handle();
        let shown = &mut cx.global_mut::<Self>().shown;
        shown.retain(|(_, other)| {
            other.upgrade().is_some() && other.entity_id() != state.entity_id()
        });
        shown.push((handle, state));
    }
    fn hidden(state: &WeakEntity<TooltipState>, cx: &mut App) {
        cx.global_mut::<Self>()
            .shown
            .retain(|(_, other)| other.entity_id() != state.entity_id());
    }
}

impl TooltipState {
    fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
        EscapeDismissal::install(cx);
        let focus = cx.focus_handle();
        let subscriptions = [
            cx.on_focus(&focus, window, |state, window, cx| {
                state.update_visibility(window, cx)
            }),
            cx.on_blur(&focus, window, |state, window, cx| {
                state.update_visibility(window, cx)
            }),
        ];
        Self {
            focus,
            overlay: cx.new(|_| TooltipOverlay::new()),
            bounds: Bounds::default(),
            label: SharedString::default(),
            hovered: false,
            active: false,
            dismissed: false,
            _subscriptions: subscriptions,
        }
    }
    fn update_visibility(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let active = self.hovered || self.focus.is_focused(window);
        if !active {
            self.dismissed = false;
        }
        let active = active && !self.dismissed;
        if active == self.active {
            return;
        }
        self.active = active;
        if active {
            let label = self.label.clone();
            let request =
                TooltipRequest::new(self.bounds, move |_, cx| text_tooltip(label.clone(), cx));
            self.overlay
                .update(cx, |overlay, cx| overlay.request_show(request, window, cx));
            EscapeDismissal::shown(window, cx.weak_entity(), cx);
        } else {
            self.overlay.update(cx, |overlay, cx| overlay.hide(cx));
            EscapeDismissal::hidden(&cx.weak_entity(), cx);
        }
    }
}

/// Creates a tooltip view for GPUI's native `.tooltip(...)` attachment point.
/// Use this on an existing interactive control to avoid nesting another button
/// and tab stop. The host control must retain its own full accessible name.
pub fn text_tooltip(label: gpui_kit::SharedString, cx: &mut App) -> gpui_kit::AnyView {
    use gpui_kit::AppContext as _;
    cx.new(|_| TextTooltip(label)).into()
}
struct TextTooltip(gpui_kit::SharedString);
impl gpui_kit::Render for TextTooltip {
    fn render(
        &mut self,
        _: &mut gpui_kit::Window,
        cx: &mut gpui_kit::Context<Self>,
    ) -> impl gpui_kit::IntoElement {
        use gpui_kit::ParentElement as _;
        let theme = UiTheme::read(cx);
        surface::tooltip(Tooltip::new("tooltip-content"), theme).child(
            div()
                .debug_selector(|| "tooltip-label".into())
                .child(self.0.clone()),
        )
    }
}

